const incoming = $input.first().json;
const body = incoming.body ?? incoming;

const required = ['executionId', 'enrollmentId', 'stepId', 'recipient', 'message', 'channel'];
const missing = required.filter((key) => !body[key]);

if (missing.length > 0) {
  throw new Error(`Invalid follow-up payload. Missing fields: ${missing.join(', ')}`);
}

return [{ json: { ...body, attempt: body.attempt ?? 1 } }];

const input = $input.first().json;
const channel = String(input.channel || 'EMAIL').toUpperCase();
const message = String(input.message || '').trim();

if (!message) {
  throw new Error('Follow-up message content is empty after template rendering');
}

return [{
  json: {
    ...input,
    channel,
    providerPayload: {
      to: input.recipient,
      subject: input.subject ?? null,
      text: message,
      channel,
      actionType: input.actionType ?? null,
      executionId: input.executionId,
      enrollmentId: input.enrollmentId,
      stepId: input.stepId,
      leadId: input.leadId ?? null,
      customerId: input.customerId ?? null
    }
  }
}];

const item = $input.first().json;
const request = $('Build Message').first().json;

const errorMessage = item?.error?.message ?? item?.errorMessage ?? item?.message ?? null;
const failed = Boolean(item?.error) || item?.success === false || Boolean(errorMessage && !item?.id && !item?.messageId);

if (failed) {
  return [{
    json: {
      success: false,
      executionId: request.executionId,
      enrollmentId: request.enrollmentId,
      stepId: request.stepId,
      error: errorMessage || 'Provider failed to deliver the follow-up message',
      retryable: true
    }
  }];
}

return [{
  json: {
    success: true,
    executionId: request.executionId,
    enrollmentId: request.enrollmentId,
    stepId: request.stepId,
    providerMessageId: item?.id ?? item?.messageId ?? `${request.channel}-${request.executionId}-${Date.now()}`,
    message: 'Follow-up executed successfully'
  }
}];
